package seokhoon.trade.application.service;
import org.junit.jupiter.api.Test; import seokhoon.trade.application.port.in.*; import seokhoon.trade.application.port.out.*; import seokhoon.trade.config.NaverNewsProperties; import seokhoon.trade.domain.scheduler.*; import java.time.*; import static org.mockito.Mockito.*;
class NewsImportSchedulerTest {@Test void providerDisabledRecordsSkippedWithoutCallingNews(){NewsUseCase news=mock(NewsUseCase.class);NaverNewsProperties props=new NaverNewsProperties();LoadMarketCalendarUseCase calendar=mock(LoadMarketCalendarUseCase.class);SchedulerExecutionHistoryPort histories=mock(SchedulerExecutionHistoryPort.class);OperationalMetricsPort metrics=mock(OperationalMetricsPort.class);Clock clock=Clock.fixed(Instant.parse("2026-06-22T00:00:00Z"),ZoneId.of("Asia/Seoul"));new NewsImportScheduler(news,props,calendar,histories,metrics,clock).execute("id");verify(histories).markSkipped(eq(SchedulerName.NEWS_IMPORT),any(),eq("NEWS_PROVIDER_DISABLED"),eq("id"),any());verify(metrics).recordSchedulerExecution(SchedulerName.NEWS_IMPORT,SchedulerExecutionStatus.SKIPPED);verifyNoInteractions(news,calendar);}}
